module main

/* sitegen builds the vlip website.
 *
 * Written in V on purpose: the project's stated final phase is a website
 * generated by vlip, and doing it in the language the site is about is the
 * cheapest possible rehearsal of that. It also forces the generator to be a real
 * program rather than a pile of templates.
 *
 * Layout on disk:
 *
 *   site/content/       not used; the page structure lives below, in V
 *   site/i18n/<code>.json   flat {"key": "text"} per language
 *   site/assets/        style.css, site.js
 *   site_out/           generated; what GitHub Pages deploys
 *
 * Strings live in JSON and are FLAT on purpose: a flat string map is the one
 * shape V's json decoder handles without surprises. Page structure is V data.
 *
 * Translation fallback: any key a language does not define falls back to
 * English, and the affected block is marked as untranslated. A partially
 * translated page says so rather than quietly mixing two languages without
 * telling the reader.
 */

import os
import json2

// ---------------------------------------------------------------- content ---

// site_root is the address GitHub Pages serves this site from. It appears in
// exactly one place -- the hreflang alternate links -- because those are the only
// URLs on the page that must be absolute. Everything else is relative, so the
// site still works from a file:// path or a different mount point.
const site_root = 'https://metif12.github.io/vlip'

struct Lang {
	code string
	name string
	dir  string // 'ltr' or 'rtl'
}

struct Item {
	title string
	body  string
	code  string
}

struct Section {
	kind    string // hero | cards | table | code | prose | steps | callout
	title   string
	sub     string
	items   []Item
	cols    []string
	rows    [][]string
	code    string
	body    []string
	tone    string
	note    string
}

struct Page {
	id    string
	url   string
	nav   string
	depth int
	secs  []Section
}

